+/** Theoretical sales use and actual consumption per item, in UTC days. */
+export function varianceReport(store, from, to) {
+  const totals = new Map();
+  const add = (itemId, field, qty) => {
+    const line = totals.get(itemId) ?? { itemId, theoretical: 0, actual: 0 };
+    line[field] = Math.round((line[field] + qty) * 1000) / 1000;
+    totals.set(itemId, line);
+  };
+  for (const sale of store.data.sales) {
+    const day = sale.soldAt.slice(0, 10);
+    if (day >= from && day <= to) for (const ingredient of sale.ingredients) add(ingredient.itemId, "theoretical", ingredient.qty);
+  }
+  for (const m of store.data.movements) {
+    const day = new Date(m.at).toISOString().slice(0, 10);
+    if (m.type !== "consume" || day < from || day > to || m.qty <= 0) continue;
+    const batch = store.data.batches.find((b) => b.id === m.batchId);
+    if (batch) add(batch.itemId, "actual", m.qty);
+  }
+  return [...totals.values()].filter((l) => l.theoretical > 0 || l.actual > 0)
+    .map((l) => ({ ...l, difference: Math.round((l.actual - l.theoretical) * 1000) / 1000 }))
+    .sort((a, b) => a.itemId - b.itemId);
+}
