diff --git a/src/io/sales-import.js b/src/io/sales-import.js
new file mode 100644
index 0000000..5aed54e
--- /dev/null
+++ b/src/io/sales-import.js
@@ -0,0 +1,50 @@
+import { AppError } from "../errors.js";
+import { memoryStore } from "../db/store.js";
+import { consume } from "../domain/batches.js";
+import { scaled } from "../domain/recipes.js";
+import { parseCsv } from "./csv.js";
+
+/** Imports complete tickets atomically and snapshots their ingredient use. */
+export function importSales(store, text) {
+  const lines = text.split(/\r?\n/);
+  const header = parseCsv(lines.shift() ?? "")[0] ?? [];
+  const columns = ["ticket", "soldAt", "dishId", "qty"];
+  if (header.length !== columns.length || columns.some((c, i) => header[i]?.trim() !== c))
+    throw new AppError("bad_request", { reason: "row 1: expected ticket,soldAt,dishId,qty" });
+  const staged = memoryStore(store.data);
+  const imported = new Set(staged.data.sales.map((s) => s.ticket));
+  const tickets = new Set();
+  let dishes = 0;
+  for (let i = 0; i < lines.length; i++) {
+    const line = lines[i];
+    if (!line.trim()) continue;
+    const fail = (reason) => { throw new AppError("bad_request", { reason: `row ${i + 2}: ${reason}` }); };
+    // Fields may be quoted, but quotes must be balanced and occur at field boundaries.
+    if (!/^(?:[^",]*|"(?:[^"]|"")*")(?:,(?:[^",]*|"(?:[^"]|"")*"))*$/.test(line)) fail("invalid CSV");
+    const fields = parseCsv(line)[0];
+    if (fields.length !== 4) fail("expected four columns");
+    const [ticket, soldAt, dishText, qtyText] = fields.map((v) => v.trim());
+    if (!ticket) fail("ticket is required");
+    if (!/^\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d(?:\.\d+)?(?:Z|[+-]\d\d:\d\d)$/.test(soldAt) || !Number.isFinite(Date.parse(soldAt)) || new Date(soldAt.slice(0, 10) + "T00:00:00Z").toISOString().slice(0, 10) !== soldAt.slice(0, 10)) fail("invalid soldAt");
+    if (!/^[1-9]\d*$/.test(dishText) || !Number.isSafeInteger(Number(dishText))) fail("invalid dishId");
+    if (!/^[1-9]\d*$/.test(qtyText) || !Number.isSafeInteger(Number(qtyText))) fail("invalid qty");
+    const dish = (staged.data.dishes ?? []).find((d) => d.id === Number(dishText));
+    if (!dish) fail("unknown dish");
+    const recipe = staged.data.recipes.find((r) => r.id === dish.recipeId);
+    if (!recipe) fail("unknown recipe");
+    if (imported.has(ticket)) continue;
+    const ingredients = scaled(recipe, Number(qtyText)).filter((n) => n.qty > 0);
+    for (const n of ingredients) {
+      try { consume(staged, n.itemId, n.qty, { at: new Date(soldAt).toISOString(), ref: `sale:${ticket}` }); }
+      catch (e) {
+        if (e instanceof AppError) fail(e.code === "not_enough_stock" ? `not enough stock for ${e.params.item}` : e.code);
+        throw e;
+      }
+    }
+    staged.data.sales.push({ ticket, soldAt: new Date(soldAt).toISOString(), dishId: dish.id, qty: Number(qtyText), ingredients });
+    tickets.add(ticket);
+    dishes += Number(qtyText);
+  }
+  store.data = staged.data;
+  return { tickets: tickets.size, dishes };
+}
